from pathlib import Path

import cv2
import numpy as np

# Add project root to path
project_root = Path.cwd().parent
if str(project_root) not in sys.path:
    sys.path.insert(0, str(project_root))

# Load environment variables
from dotenv import load_dotenv
load_dotenv(project_root / ".env")

from src.utils import load_json, save_json, load_image
from src.alignment_wrapper import load_template_zones
from src.labels_generator import (
    generate_fields_json,
    generate_labels_json,
    generate_labels_batch,
    validate_training_data,
)
from src.ocr_generator import extract_words_from_ocr, get_page_dimensions

print(f"Project root: {project_root}")

# %% [markdown]
# ## 1. Configuration

# %%
# Paths
DATA_DIR = project_root / "data"
TRAINING_DIR = DATA_DIR / "training"
DEBUG_DIR = DATA_DIR / "debug"
TEMPLATES_DIR = project_root / "templates"

TEMPLATE_JSON_PATH = TEMPLATES_DIR / "template.json"

# Create debug directory if it doesn't exist
DEBUG_DIR.mkdir(parents=True, exist_ok=True)

print(f"Training directory: {TRAINING_DIR}")
print(f"Debug directory: {DEBUG_DIR}")
print(f"Template JSON: {TEMPLATE_JSON_PATH}")

# List training files
